-- eva-lpm: synthesized K-12 curriculum content, seeded into its own private
-- OpenLPM Project Space, from eva-graph/curriculum_models/eva-lpm_v1_1-v1.0.0-
-- 2026-06-10.json (72 CFItems, 130 CFAssociations, 33% complete per the source's
-- own completionPercentage). Full design and the three decisions behind this
-- migration's scope are in lab_manager/docs/design-notes/
-- eva-lpm-openlpm-synthesis-and-migration-strategy-2026-10-01.md -- read that
-- doc, not just this file, before changing anything here.
--
-- Deliberately out of scope (confirmed with Dustin 2026-10-01): the separate
-- MPI-EVA department-research dataset (eva-graph/mpi-eva-graph/) -- none of its
-- content (real department names, directors, papers) is seeded here. Only the
-- K-12 curriculum half moves into OpenLPM in this pass.
--
-- All five new projects are seeded with is_private = TRUE: this is real,
-- AI-assisted-human-directed draft content (eva-lpm's own provenance fields
-- self-label every item 'validationStatus: draft'), explicitly not MPI-EVA-
-- affiliated or endorsed, not yet reviewed by any subject-matter expert beyond
-- its own author -- not ready for OpenLPM's general, signed-in user base to
-- browse as if it were settled content.
--
-- UUIDs below are deterministic (uuid_generate_v5-equivalent, computed in
-- Python at migration-authoring time, not at apply time) so the generator
-- script (lab_manager session, 2026-10-01) could be re-run idempotently during
-- drafting without producing a different id each time.

DO $MIGRATION$
DECLARE
  v_eva_lpm_id UUID := '7098b8f6-e33e-53d1-bffe-d94d209d045a';
  v_sachsen_id UUID := '5b8b6589-bb3a-5dba-8e3b-9d4cc99128d2';
  v_sachsen_anhalt_id UUID := 'a76a8f17-ad9e-59a0-be4d-71f386f19dc5';
  v_thueringen_id UUID := 'f7ef96b8-770f-5257-8d40-99bb191e5fb4';
  v_us_interdisciplinary_id UUID := '22de8d22-3a3e-51d5-b078-aee52d2698d6';
BEGIN

  -- ------------------------------------------------------------------------
  -- Projects: the eva-lpm Space plus 4 nested sub-projects
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Base links: all 5 projects can import from ConceptBase (public, the only
  -- Foundational Repo with a live import path today); none can propose PRs
  -- back yet (that write-back pipeline isn't built anywhere in OpenLPM).
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Source declarations: what each project's content is drawn from
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Schema elements: 13-concept compression vocabulary + 4 cross-cutting themes
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Data objects: 7 strands, 1 sub-strand, 54 learning objectives, 1 capstone
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Connections: structural links between data objects (strand/sub-strand/
  -- learning-objective/capstone), carried over verbatim from the source
  -- CFAssociations (isChildOf/isRelatedTo/prerequisiteOf) -- kind='asserted'
  -- because these are the source curriculum's own declared structure, not a
  -- didactic suggestion; status='accepted', matching how EvoMentor's own real
  -- ingested content was grandfathered rather than left pending review.
  -- ------------------------------------------------------------------------

  -- ------------------------------------------------------------------------
  -- Object tags: learning objectives linked to the cross-cutting theme they
  -- instantiate (both endpoints weren't data objects, so lpm_connections --
  -- which FKs to lpm_data_objects on both sides -- doesn't fit; this is
  -- exactly the data_object<->schema_element mechanism lpm_object_tags exists
  -- for).
  -- ------------------------------------------------------------------------

END $MIGRATION$;