  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, is_private, maturity, parent_project_id, focus_type, region_tags, theme_tags, working_languages)
  VALUES
  (v_eva_lpm_id, $J$eva-lpm$J$, $J$eva-lpm$J$, $J$A K-12 interdisciplinary curriculum framework organized around the question “What does it mean to be human?”, grounded in evolutionary anthropology: 7 subject strands (seeded from MPI-EVA department research vocabulary as content seed material only -- eva-lpm is not affiliated with, does not represent, and is not endorsed by MPI-EVA or any research institution), 4 cross-cutting themes, 4 grade bands (K-2, 3-5, 6-8, 9-12), and a 13-concept cross-cutting compression-expression vocabulary. 33% complete (54 of ~163 planned learning objectives) as of the source migration date. Every item is self-labeled draft / AI-assisted-human-directed in its own provenance metadata -- not yet reviewed by any subject-matter expert beyond its own author. Content touching Indigenous oral traditions, kinship systems, or cultural phylogenies must be co-developed with relevant knowledge holders before use with the communities whose traditions are represented (see the source document's own indigenousKnowledgeStatement). Migrated from eva-graph/curriculum_models/, which remains the live data source for the Ask Eva app and is not being deleted or edited by this migration.$J$, 'active', 'in-development', $J$Real, in-process curriculum content, not a synthetic comparison object -- but also not yet field-validated: self-labeled draft throughout, 33% complete, unreviewed by any subject-matter expert outside its own authoring process.$J$, 'hosted', TRUE, 'draft', NULL, 'general', '{}'::TEXT[], '{}'::TEXT[], ARRAY['en']::TEXT[]),
  (v_sachsen_id, $J$eva-lpm-sachsen$J$, $J$eva-lpm — Sachsen$J$, $J$German-language regional crosswalk of eva-lpm's K-12 curriculum against Saxony's (Sachsen) real Lehrplan, building on existing alignment work already drafted in eva-graph/curriculum_models/wkprc-visit-guides/ (three grade-band Pongoland zoo visit guides, each adapting specific eva-lpm learning objectives). Source content declared (see project_source_declarations) but not yet imported as structured items.$J$, 'planning', 'in-development', $J$Nested under eva-lpm; inherits its parent's draft, unreviewed status.$J$, 'hosted', TRUE, 'draft', v_eva_lpm_id, 'regional', ARRAY['DE-SN']::TEXT[], '{}'::TEXT[], ARRAY['de']::TEXT[]),
  (v_sachsen_anhalt_id, $J$eva-lpm-sachsen-anhalt$J$, $J$eva-lpm — Sachsen-Anhalt$J$, $J$German-language regional crosswalk of eva-lpm's K-12 curriculum against Saxony-Anhalt's (Sachsen-Anhalt) Lehrplan. No existing alignment work exists anywhere in the ecosystem for this jurisdiction yet -- starts structurally empty, genuinely new territory.$J$, 'planning', 'in-development', $J$Nested under eva-lpm; inherits its parent's draft, unreviewed status.$J$, 'hosted', TRUE, 'draft', v_eva_lpm_id, 'regional', ARRAY['DE-ST']::TEXT[], '{}'::TEXT[], ARRAY['de']::TEXT[]),
  (v_thueringen_id, $J$eva-lpm-thueringen$J$, $J$eva-lpm — Thüringen$J$, $J$German-language regional crosswalk of eva-lpm's K-12 curriculum against Thüringen's real Biologie Lehrplan, building on an existing drafted crosswalk already in eva-graph/curriculum_models/eva-lpm_biologie_thuringia_de_v1.json. Source content declared (see project_source_declarations) but not yet imported as structured items.$J$, 'planning', 'in-development', $J$Nested under eva-lpm; inherits its parent's draft, unreviewed status.$J$, 'hosted', TRUE, 'draft', v_eva_lpm_id, 'regional', ARRAY['DE-TH']::TEXT[], '{}'::TEXT[], ARRAY['de']::TEXT[]),
  (v_us_interdisciplinary_id, $J$eva-lpm-us-interdisciplinary$J$, $J$eva-lpm US Interdisciplinary$J$, $J$Thematic crosswalk of eva-lpm's K-12 learning aims against major US standards frameworks (NGSS, AI4K12, and other relevant frameworks to be identified). Starts structurally empty -- no existing crosswalk work for this scope exists anywhere in the ecosystem yet.$J$, 'planning', 'in-development', $J$Nested under eva-lpm; inherits its parent's draft, unreviewed status.$J$, 'hosted', TRUE, 'draft', v_eva_lpm_id, 'thematic', '{}'::TEXT[], ARRAY['ngss','ai4k12','us-standards']::TEXT[], ARRAY['en']::TEXT[]);
